    if len(outside) < 3:
        return panel
    # Find the L's corner and its horizontal/vertical arms.
    corner = None
    for r, c, v in outside:
        same_row = [x for x in outside if x[0] == r and x[1] != c]
        same_col = [x for x in outside if x[1] == c and x[0] != r]
