    hd = 'left' if hmark[1] < c else 'right'
    vd = 'up' if vmark[0] < r else 'down'
    guide = {x[2] for x in outside}
    core = [[v if v not in guide else 1 for v in row] for row in panel]
    if (hd, vd) == ('left', 'down'):
